CREATE SCHEMA IF NOT EXISTS public;
SET search_path TO public;

-- Справочники: название обязательно и не пустое

CREATE TABLE "Facultys" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(150) NOT NULL CHECK (btrim("Name") <> '')
);

CREATE TABLE "Department" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(150) NOT NULL CHECK (btrim("Name") <> ''),
  "FacultyID" integer NOT NULL
);

CREATE TABLE "Specialties" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(150) NOT NULL CHECK (btrim("Name") <> ''),
  "FacultyID" integer NOT NULL
);

CREATE TABLE "StudyFormat" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(50) NOT NULL CHECK (btrim("Name") <> '')
);

CREATE TABLE "FundingType" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Type" varchar(100) NOT NULL CHECK (btrim("Type") <> '')
);

CREATE TABLE "Status" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Status" varchar(100) NOT NULL CHECK (btrim("Status") <> '')
);

CREATE TABLE "Student" (
  "StudentID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "FirstName" varchar(100) NOT NULL CHECK (btrim("FirstName") <> ''),
  "MiddleName" varchar(100) CHECK (btrim("MiddleName") <> ''),
  "LastName" varchar(100) NOT NULL CHECK (btrim("LastName") <> ''),
  "FundingTypeID" integer NOT NULL,
  "StartDate" date,
  "StatusID" integer NOT NULL
);

CREATE TABLE "Group" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(100) NOT NULL CHECK (btrim("Name") <> ''),
  "SpecialtyID" integer NOT NULL,
  "StudyYear" integer NOT NULL CHECK ("StudyYear" BETWEEN 1 AND 6),
  "StudyFormatID" integer NOT NULL
);

CREATE TABLE "StudentGroup" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StudentID" integer NOT NULL,
  "GroupID" integer NOT NULL,
  UNIQUE ("StudentID", "GroupID")
);

CREATE TABLE "Discipline" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(150) NOT NULL CHECK (btrim("Name") <> ''),
  "DepartmentID" integer NOT NULL
);

CREATE TABLE "Types" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(100) NOT NULL CHECK (btrim("Name") <> '')
);

CREATE TABLE "DisciplineHours" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "DisciplineID" integer NOT NULL,
  "TypeID" integer NOT NULL,
  "Hours" integer NOT NULL CHECK ("Hours" > 0),
  UNIQUE ("DisciplineID", "TypeID")
);

CREATE TABLE "GroupDiscipline" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "GroupID" integer NOT NULL,
  "DisciplineID" integer NOT NULL,
  "SemesterNum" integer NOT NULL CHECK ("SemesterNum" BETWEEN 1 AND 12),
  UNIQUE ("GroupID", "DisciplineID", "SemesterNum")
);

CREATE TABLE "Positions" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(100) NOT NULL CHECK (btrim("Name") <> '')
);

CREATE TABLE "Degrees" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(100) NOT NULL CHECK (btrim("Name") <> '')
);

CREATE TABLE "Teacher" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "FirstName" varchar(100) NOT NULL CHECK (btrim("FirstName") <> ''),
  "MiddleName" varchar(100) CHECK (btrim("MiddleName") <> ''),
  "LastName" varchar(100) NOT NULL CHECK (btrim("LastName") <> ''),
  "DepartmentID" integer NOT NULL,
  "PositionID" integer NOT NULL,
  "DegreeID" integer
);

CREATE TABLE "Teaches" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "GroupDisciplineID" integer NOT NULL,
  "TeacherID" integer NOT NULL,
  "TypeID" integer NOT NULL,
  UNIQUE ("GroupDisciplineID", "TeacherID", "TypeID")
);

CREATE TABLE "AssessmentType" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(100) NOT NULL CHECK (btrim("Name") <> '')
);

CREATE TABLE "Assessment" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "AssessmentTypeID" integer NOT NULL,
  "MaxAttempts" integer NOT NULL DEFAULT 1 CHECK ("MaxAttempts" BETWEEN 1 AND 10),
  "GroupDisciplineID" integer NOT NULL,
  UNIQUE ("GroupDisciplineID", "AssessmentTypeID")
);

CREATE TABLE "Attempt" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "AssessmentID" integer NOT NULL,
  "StudentID" integer NOT NULL,
  "TeacherID" integer NOT NULL,
  "Grade" integer NOT NULL CHECK ("Grade" BETWEEN 1 AND 10),
  "Date" date NOT NULL,
  "Note" text
);

COMMENT ON COLUMN "StudyFormat"."Name" IS 'Очная, заочная, вечерняя и другие формы обучения';
COMMENT ON COLUMN "Group"."StudyYear" IS 'Курс, от 1 до 6';
COMMENT ON COLUMN "GroupDiscipline"."SemesterNum" IS 'Номер семестра, от 1 до 12';
COMMENT ON COLUMN "Attempt"."Grade" IS 'Оценка от 1 до 10';

-- Внешние ключи. По умолчанию удалить запись, на которую ссылаются, нельзя.
-- Каскадно удаляются только часы дисциплины и членство студента в группах.

ALTER TABLE "Department" ADD FOREIGN KEY ("FacultyID") REFERENCES "Facultys" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Specialties" ADD FOREIGN KEY ("FacultyID") REFERENCES "Facultys" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Student" ADD FOREIGN KEY ("FundingTypeID") REFERENCES "FundingType" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Student" ADD FOREIGN KEY ("StatusID") REFERENCES "Status" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Group" ADD FOREIGN KEY ("SpecialtyID") REFERENCES "Specialties" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Group" ADD FOREIGN KEY ("StudyFormatID") REFERENCES "StudyFormat" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "StudentGroup" ADD FOREIGN KEY ("StudentID") REFERENCES "Student" ("StudentID") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "StudentGroup" ADD FOREIGN KEY ("GroupID") REFERENCES "Group" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Discipline" ADD FOREIGN KEY ("DepartmentID") REFERENCES "Department" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "DisciplineHours" ADD FOREIGN KEY ("DisciplineID") REFERENCES "Discipline" ("ID") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "DisciplineHours" ADD FOREIGN KEY ("TypeID") REFERENCES "Types" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "GroupDiscipline" ADD FOREIGN KEY ("GroupID") REFERENCES "Group" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "GroupDiscipline" ADD FOREIGN KEY ("DisciplineID") REFERENCES "Discipline" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Teacher" ADD FOREIGN KEY ("DepartmentID") REFERENCES "Department" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Teacher" ADD FOREIGN KEY ("PositionID") REFERENCES "Positions" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Teacher" ADD FOREIGN KEY ("DegreeID") REFERENCES "Degrees" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Teaches" ADD FOREIGN KEY ("GroupDisciplineID") REFERENCES "GroupDiscipline" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Teaches" ADD FOREIGN KEY ("TeacherID") REFERENCES "Teacher" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Teaches" ADD FOREIGN KEY ("TypeID") REFERENCES "Types" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Assessment" ADD FOREIGN KEY ("AssessmentTypeID") REFERENCES "AssessmentType" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Assessment" ADD FOREIGN KEY ("GroupDisciplineID") REFERENCES "GroupDiscipline" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Attempt" ADD FOREIGN KEY ("AssessmentID") REFERENCES "Assessment" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Attempt" ADD FOREIGN KEY ("StudentID") REFERENCES "Student" ("StudentID") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Attempt" ADD FOREIGN KEY ("TeacherID") REFERENCES "Teacher" ("ID") DEFERRABLE INITIALLY IMMEDIATE;

-- Правила, которые не выразить через CHECK: проверяются триггерами

-- Вид занятий в Teaches должен быть в часах этой дисциплины
CREATE FUNCTION "check_teaches"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM "GroupDiscipline" gd
    JOIN "DisciplineHours" dh ON dh."DisciplineID" = gd."DisciplineID"
    WHERE gd."ID" = NEW."GroupDisciplineID" AND dh."TypeID" = NEW."TypeID"
  ) THEN
    RAISE EXCEPTION 'У этой дисциплины нет часов такого вида занятий';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "teaches_check" BEFORE INSERT OR UPDATE ON "Teaches"
FOR EACH ROW EXECUTE FUNCTION "check_teaches"();

-- Попытка: студент из группы этой дисциплины, преподаватель её ведёт,
-- число попыток не больше MaxAttempts
CREATE FUNCTION "check_attempt"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  gd_id integer;
  max_attempts integer;
BEGIN
  SELECT "GroupDisciplineID", "MaxAttempts" INTO gd_id, max_attempts
  FROM "Assessment" WHERE "ID" = NEW."AssessmentID";

  IF NOT EXISTS (
    SELECT 1 FROM "GroupDiscipline" gd
    JOIN "StudentGroup" sg ON sg."GroupID" = gd."GroupID"
    WHERE gd."ID" = gd_id AND sg."StudentID" = NEW."StudentID"
  ) THEN
    RAISE EXCEPTION 'Студент не учится в группе, у которой эта аттестация';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM "Teaches"
    WHERE "GroupDisciplineID" = gd_id AND "TeacherID" = NEW."TeacherID"
  ) THEN
    RAISE EXCEPTION 'Преподаватель не ведёт эту дисциплину у группы';
  END IF;

  IF (SELECT count(*) FROM "Attempt"
      WHERE "AssessmentID" = NEW."AssessmentID" AND "StudentID" = NEW."StudentID"
        AND "ID" <> NEW."ID") >= max_attempts THEN
    RAISE EXCEPTION 'Превышено число попыток: %', max_attempts;
  END IF;

  RETURN NEW;
END $$;

CREATE TRIGGER "attempt_check" BEFORE INSERT OR UPDATE ON "Attempt"
FOR EACH ROW EXECUTE FUNCTION "check_attempt"();

-- Новые записи нельзя датировать прошлым числом: дата оценки и дата зачисления не раньше сегодня.
-- Проверка только при добавлении, поэтому старые записи можно спокойно править.
CREATE FUNCTION "check_not_past"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) ->> TG_ARGV[0])::date < CURRENT_DATE THEN
    RAISE EXCEPTION 'Дата (%) не может быть раньше сегодняшней', TG_ARGV[0];
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "attempt_date_not_past" BEFORE INSERT ON "Attempt"
FOR EACH ROW EXECUTE FUNCTION "check_not_past"('Date');

CREATE TRIGGER "student_start_not_past" BEFORE INSERT ON "Student"
FOR EACH ROW EXECUTE FUNCTION "check_not_past"('StartDate');
